WITH ev(src,child,ex,rate,cumd_child,pcum_child,pex_child) AS (VALUES ('ALKS','MURA','2023-11-16'::date,0.1,NULL::date,NULL::numeric,3.8),('APTV','VGNT','2026-04-01'::date,0.33333333333,'2026-03-31'::date,31.85,27.85),('ARMK','VSTS','2023-10-02'::date,0.5,'2023-09-29'::date,19.3,17.01),('BAM','BAMR','2021-06-28'::date,0.0069,NULL::date,NULL::numeric,62.1),('BDX','EMBC','2022-04-01'::date,0.2,'2022-03-31'::date,33.33,30.5),('BDX','WAT','2026-02-10'::date,0.135343142914,'2026-02-09'::date,328.14,327.02),('BN','BAM','2022-12-12'::date,0.25,'2022-12-09'::date,32,32.4),('BWA','PHIN','2023-07-05'::date,0.2,'2023-07-03'::date,30.05,36.75),('CMCSA','VSNT','2026-01-05'::date,0.04,'2026-01-02'::date,46.65,40.57),('CTVA','VYLR','2026-10-01'::date,1.0,NULL::date,NULL::numeric,68.26),('DD','Q','2025-11-03'::date,0.5,'2025-10-31'::date,95,97),('DHR','VLTO','2023-10-02'::date,0.333333333,'2023-09-29'::date,84.56,85.12),('DTE','DTM','2021-07-01'::date,0.5,'2021-06-30'::date,38.66,42.02),('EHC','EHAB','2022-07-01'::date,0.5,'2022-06-30'::date,22.97,22.74),('EXC','CEG','2022-02-02'::date,0.33333,NULL::date,NULL::numeric,53.01),('FBIN','MBC','2022-12-15'::date,1.0,'2022-12-14'::date,9,7.7),('FDX','FDXF','2026-06-01'::date,0.5,'2026-05-29'::date,160.37,149.53),('FLEX','NXT','2024-01-03'::date,0.174185,'2024-01-02'::date,47.42,46.41),('FNF','FG','2022-12-01'::date,0.068,'2022-11-30'::date,22.99,19.13),('FNF','FG','2025-12-17'::date,0.06,'2025-12-16'::date,34.48,32.83),('FTAI','FIP','2022-08-02'::date,1.0,'2022-08-01'::date,3.3,2.7),('FTI','THNPF','2021-02-16'::date,0.2,NULL::date,NULL::numeric,NULL::numeric),('FTV','RAL','2025-06-30'::date,0.333333333,'2025-06-27'::date,52.98,48.49),('GE','GEHC','2023-01-04'::date,0.33333,'2023-01-03'::date,56,60.49),('GE','GEV','2024-04-02'::date,0.25,'2024-04-01'::date,142.02,140),('GE','WAB','2019-02-25'::date,0.005371,'2019-02-22'::date,75,78.06),('HON','HONA','2026-06-29'::date,0.5,'2026-06-26'::date,221.01,220.19),('HON','SOLS','2025-10-30'::date,0.25,'2025-10-29'::date,49.25,48.74),('ILMN','GRAL','2024-06-25'::date,0.166666667,'2024-06-24'::date,18.63,17),('IP','SLVM','2021-10-01'::date,0.09091,'2021-09-30'::date,32.67,33),('J','AMTM','2024-09-30'::date,1.0,'2024-09-27'::date,25.67,32.25),('J','AMTM','2025-05-16'::date,0.060835,'2025-05-15'::date,21.6,21.84),('JEF','VTS','2023-01-17'::date,0.11769,'2023-01-13'::date,15.29,14.4),('LBTYB','SNRBY','2024-11-13'::date,2.0,NULL::date,NULL::numeric,NULL::numeric),('LEN','MRP','2025-01-21'::date,0.5,NULL::date,NULL::numeric,NULL::numeric),('LEN.B','MRP','2025-01-21'::date,0.5,NULL::date,NULL::numeric,NULL::numeric),('LGND','OABI','2022-11-02'::date,4.90007,'2022-11-01'::date,6.125,2.41),('LH','FTRE','2023-07-03'::date,1.0,'2023-06-30'::date,34.01,36.84),('MDU','ECG','2024-11-01'::date,0.25,'2024-10-31'::date,51.5,52.49),('MDU','KNF','2023-06-01'::date,0.25,'2023-05-31'::date,36.65,35.02),('MIDD','MFP','2026-07-07'::date,1.0,'2026-07-06'::date,35.05,36.6),('MMM','SOLV','2024-04-01'::date,0.25,'2024-03-28'::date,69.55,69.1),('MOD','THRM','2026-10-02'::date,0.44619,'2026-10-01'::date,33.63,31.3),('PFE','VTRS','2020-11-17'::date,0.1240788849,'2020-11-16'::date,15.66,16.34),('POST','BRBR','2022-03-11'::date,1.26779,'2022-03-10'::date,25.15,24.52),('PUK','JXN','2021-09-20'::date,0.05,'2021-09-17'::date,25.42,26.1),('REZI','ADIG','2026-08-04'::date,0.5,'2026-08-03'::date,22.06,22),('SPGI','MBGL','2026-07-01'::date,1.0,'2026-06-30'::date,22.05,21.19),('T','WBD','2022-04-11'::date,0.24192,'2022-04-08'::date,24.47,24.78),('WDC','SNDK','2025-02-24'::date,0.333333333,'2025-02-21'::date,50.37,48.6),('XPO','RXO','2022-11-01'::date,1.0,'2022-10-31'::date,21,19.06),('ZBH','ZIMV','2022-03-01'::date,0.1,NULL::date,NULL::numeric,25.53)),
x AS (SELECT ev.*, s.id sid,
  CASE WHEN ev.src='HON' AND ev.ex='2026-06-29' THEN 0.5 ELSE 1 END AS sh,
  (SELECT close FROM price_daily p WHERE p.stock_id=s.id AND p.trade_date<ev.ex ORDER BY trade_date DESC LIMIT 1) cum,
  (SELECT trade_date FROM price_daily p WHERE p.stock_id=s.id AND p.trade_date<ev.ex ORDER BY trade_date DESC LIMIT 1) cumd,
  (SELECT close FROM price_daily p WHERE p.stock_id=s.id AND p.trade_date=ev.ex) exc
 FROM ev JOIN stock s ON s.market_code='US' AND s.ticker=ev.src),
y AS (SELECT x.*,
  (SELECT close FROM market_index_daily WHERE index_code='US' AND trade_date=x.ex)/(SELECT close FROM market_index_daily WHERE index_code='US' AND trade_date=x.cumd)-1 AS ri,
  (SELECT stddev_samp(r) FROM (SELECT close/lag(close) OVER (ORDER BY trade_date)-1 r FROM (SELECT trade_date, close FROM price_daily p WHERE p.stock_id=x.sid AND p.trade_date<=x.cumd ORDER BY trade_date DESC LIMIT 61) q) z) sd
 FROM x WHERE x.exc IS NOT NULL AND x.cum IS NOT NULL)
SELECT src, child, ex, sh,
  -- 옛 주식 기준 ex 종가: s·P(ex)
  round(((sh*exc + rate*pex_child)/cum - 1 - ri)/sd, 2) AS z_fb,
  round(((sh*exc)/(cum - rate*pcum_child) - 1 - ri)/sd, 2) AS z_fc,
  round(100*((sh*exc + rate*pex_child)/cum - 1),1) AS adj_fb, round(100*((sh*exc)/(cum - rate*pcum_child) - 1),1) AS adj_fc,
  round(100*ri,1) idx, round(100*sd,2) sd
FROM y ORDER BY ex
